begin;
set local search_path=public,extensions;
select plan(25);

select has_column('public','referral_conversions','audience_type','conversion stores immutable link audience');
select ok(exists(select 1 from pg_constraint where conname='referral_conversion_link_audience_fk'),'conversion audience is FK-bound to referral link audience');
select ok((select pg_get_functiondef(p.oid)like'%REFERRED_PROVIDER%PROVIDER%'and pg_get_functiondef(p.oid)like'%REWARD_WALLET_AUDIENCE_MISMATCH%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='award_reward'),'reward wallet type is derived strictly from audience');
select ok((select pg_get_functiondef(p.oid)like'%wallet_kind=''PROVIDER''%'and pg_get_functiondef(p.oid)like'%PROVIDER_REWARD_AUTHORITY_REQUIRED%'and pg_get_functiondef(p.oid)like'%reward_award_approvals%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='issue_credits'),'provider wallet issuance is limited to approved referral rewards');
select ok((select pg_get_functiondef(p.oid)like'%valid_reward_organization_source%'and pg_get_functiondef(p.oid)like'%AUTHORITATIVE_ORGANIZATION_SOURCE_REQUIRED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_reward_source_event'),'organization rewards require a durable authoritative source');
select ok((select pg_get_functiondef(p.oid)like'%diagnostic_recommendations%'and pg_get_functiondef(p.oid)like'%client_projects%'and pg_get_functiondef(p.oid)like'%contracts%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='valid_reward_organization_source'),'authoritative organization sources resolve to tenant domain records');
select ok((select pg_get_functiondef(p.oid)like'%CLIENT_COMPLIANCE_EVIDENCE%'and pg_get_functiondef(p.oid)like'%PROVIDER_DOCUMENT_VERSION%'and pg_get_functiondef(p.oid)like'%organization_id=p_organization_id%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='valid_tenant_baseline_evidence'),'baseline evidence resolves in approved tenant registries');
select ok((select count(*)=1 from pg_trigger where tgname='baseline_submission_tenant_evidence_guard'and not tgisinternal),'every baseline submission invokes tenant evidence validation');
select ok((select pg_get_functiondef(p.oid)like'%REFERRAL_REQUEST_DENIED%'and pg_get_functiondef(p.oid)not like'%ACTIVE_REFERRAL_LINK_REQUIRED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_referral_touchpoint'),'touchpoint failures use a uniform anti-oracle response');
select ok((select count(*)=2 and bool_and(p.prosecdef and p.proconfig::text like'%search_path=pg_catalog%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname=any(array['valid_reward_organization_source','valid_tenant_baseline_evidence'])),'source resolvers are hardened security-definer functions');
select ok(not has_function_privilege('authenticated','private.valid_tenant_baseline_evidence(uuid,jsonb)','EXECUTE')and not has_function_privilege('service_role','private.valid_reward_organization_source(uuid,text,text)','EXECUTE'),'private source resolvers are not API surfaces');
select ok((select pg_get_functiondef(p.oid)not like'%update public.credit_wallets%'and pg_get_functiondef(p.oid)like'%insert into public.credit_ledger_entries%'and pg_get_functiondef(p.oid)like'%insert into public.credit_lots%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='issue_credits'),'credit issuance appends immutable ledger and lot records without balance mutation');

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values
 ('a7100000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','audience-admin1@example.invalid','',now(),'{}','{}',now(),now()),
 ('a7100000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','audience-admin2@example.invalid','',now(),'{}','{}',now(),now()),
 ('a7100000-0000-4000-8000-000000000003','00000000-0000-0000-0000-000000000000','authenticated','authenticated','audience-client@example.invalid','',now(),'{}','{}',now(),now());
insert into public.organizations(id,legal_name,display_name,status,created_by)values
 ('b7100000-0000-4000-8000-000000000001','Audience Source','Audience Source','ACTIVE','a7100000-0000-4000-8000-000000000001'),
 ('b7100000-0000-4000-8000-000000000002','Audience Client','Audience Client','ACTIVE','a7100000-0000-4000-8000-000000000003'),
 ('b7100000-0000-4000-8000-000000000003','Foreign Evidence','Foreign Evidence','ACTIVE','a7100000-0000-4000-8000-000000000001');
insert into public.organization_memberships(id,organization_id,user_id,status,activated_at)values('c7100000-0000-4000-8000-000000000001','b7100000-0000-4000-8000-000000000002','a7100000-0000-4000-8000-000000000003','ACTIVE',now());
insert into public.organization_member_roles(membership_id,role_code)values('c7100000-0000-4000-8000-000000000001','CLIENT_OWNER');
insert into public.platform_user_roles(user_id,role_code)values('a7100000-0000-4000-8000-000000000001','SUPER_ADMIN'),('a7100000-0000-4000-8000-000000000002','SUPER_ADMIN');
insert into public.credit_wallets(id,organization_id,wallet_type)values
 ('d7100000-0000-4000-8000-000000000001','b7100000-0000-4000-8000-000000000002','CLIENT'),
 ('d7100000-0000-4000-8000-000000000012','b7100000-0000-4000-8000-000000000002','PROVIDER');
insert into public.client_projects(id,organization_id,project_code,status,created_by)values('d7100000-0000-4000-8000-000000000002','b7100000-0000-4000-8000-000000000002','REWARD71','ACTIVE','a7100000-0000-4000-8000-000000000003');
insert into public.reward_rule_versions(id,rule_code,version_number,status,trigger_event,audience_type,bonus_credits,per_recipient_cap_credits,global_cap_credits,window_days,cooldown_hours,credit_validity_days,eligibility_rule,requires_approval,effective_from,content_hash,change_reason,created_by)values
 ('d7100000-0000-4000-8000-000000000003','PROJECT_REWARD71',1,'ACTIVE','PROJECT_COMPLETED','CLIENT_ORGANIZATION',25,50,500,30,0,90,'{"completed":true}',true,clock_timestamp()-interval'1 day',repeat('1',64),'Audience happy path','a7100000-0000-4000-8000-000000000001'),
 ('d7100000-0000-4000-8000-000000000004','PROVIDER_REWARD71',1,'ACTIVE','REFERRAL_VERIFIED','REFERRED_PROVIDER',15,30,300,30,0,90,'{"verified":true}',true,clock_timestamp()-interval'1 day',repeat('2',64),'Wallet mismatch test','a7100000-0000-4000-8000-000000000001');
insert into public.client_compliance_cases(id,organization_id,status,created_by)values
 ('d7100000-0000-4000-8000-000000000005','b7100000-0000-4000-8000-000000000002','PROFILE_IN_PROGRESS','a7100000-0000-4000-8000-000000000003'),
 ('d7100000-0000-4000-8000-000000000006','b7100000-0000-4000-8000-000000000003','PROFILE_IN_PROGRESS','a7100000-0000-4000-8000-000000000001');
insert into public.client_compliance_evidence(id,compliance_case_id,organization_id,evidence_type,object_path,file_sha256,review_status,reviewed_by,reviewed_at,created_by)values
 ('d7100000-0000-4000-8000-000000000007','d7100000-0000-4000-8000-000000000005','b7100000-0000-4000-8000-000000000002','TAX_DOCUMENT','tenant/evidence/valid.pdf',repeat('3',64),'VERIFIED','a7100000-0000-4000-8000-000000000001',now(),'a7100000-0000-4000-8000-000000000003'),
 ('d7100000-0000-4000-8000-000000000008','d7100000-0000-4000-8000-000000000006','b7100000-0000-4000-8000-000000000003','TAX_DOCUMENT','foreign/evidence/file.pdf',repeat('4',64),'VERIFIED','a7100000-0000-4000-8000-000000000002',now(),'a7100000-0000-4000-8000-000000000001');
-- Trusted fixture state only: the runtime transition below still exercises the
-- production dual-control referral command under authenticated JWTs.
set local session_replication_role=replica;
update public.client_compliance_cases set status='VERIFIED',verified_at=now(),activated_at=now() where id in('d7100000-0000-4000-8000-000000000005','d7100000-0000-4000-8000-000000000006');
set local session_replication_role=origin;
insert into public.referral_links(id,source_organization_id,referral_code,audience_type,campaign_reference,status,expires_at,max_conversions,created_by,correlation_id)values('d7100000-0000-4000-8000-000000000009','b7100000-0000-4000-8000-000000000001','AUDIENCE71','CLIENT','AUDIENCE_TEST','ACTIVE',clock_timestamp()+interval'30 days',10,'a7100000-0000-4000-8000-000000000001','e7100000-0000-4000-8000-000000000001');
insert into public.referral_conversions(id,referral_link_id,source_organization_id,target_organization_id,audience_type,conversion_stage,origin_snapshot,registered_by,row_version)values('d7100000-0000-4000-8000-000000000010','d7100000-0000-4000-8000-000000000009','b7100000-0000-4000-8000-000000000001','b7100000-0000-4000-8000-000000000002','CLIENT','PROFILE_STARTED','{"campaign":"AUDIENCE_TEST"}','a7100000-0000-4000-8000-000000000003',2);
insert into public.referral_conversion_events(referral_conversion_id,source_organization_id,from_stage,to_stage,evidence_refs,evidence_hash,correlation_id,actor_user_id)values
 ('d7100000-0000-4000-8000-000000000010','b7100000-0000-4000-8000-000000000001',null,'REGISTERED','["registration:71"]',repeat('5',64),'e7100000-0000-4000-8000-000000000002','a7100000-0000-4000-8000-000000000003'),
 ('d7100000-0000-4000-8000-000000000010','b7100000-0000-4000-8000-000000000001','REGISTERED','PROFILE_STARTED','["profile:71"]',repeat('6',64),'e7100000-0000-4000-8000-000000000003','a7100000-0000-4000-8000-000000000003');
create temporary table p20_observed(k text primary key,v jsonb);grant select,insert on p20_observed to authenticated;

set local role authenticated;
select set_config('request.jwt.claim.sub','a7100000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a7100000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into p20_observed values('source',public.record_reward_source_event('b7100000-0000-4000-8000-000000000002','PROJECT_COMPLETED','CLIENT_ORGANIZATION','CLIENT_PROJECT','d7100000-0000-4000-8000-000000000002','{"completed":true}','["project:d7100000-0000-4000-8000-000000000002"]',repeat('7',64),clock_timestamp(),'reward-source-71'));
insert into p20_observed values('verified',public.advance_referral_conversion('d7100000-0000-4000-8000-000000000010','VERIFIED','["compliance:d7100000-0000-4000-8000-000000000005"]',repeat('8',64),2,'referral-verify-71'));
select set_config('request.jwt.claim.sub','a7100000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"a7100000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
insert into p20_observed values('approval',public.decide_reward_award((select(v->>'source_event_id')::uuid from p20_observed where k='source'),'d7100000-0000-4000-8000-000000000003','APPROVED','Independent approved project completion','reward-approve-71'));
insert into p20_observed values('active',public.advance_referral_conversion('d7100000-0000-4000-8000-000000000010','ACTIVE','["activation:dual-control"]',repeat('9',64),3,'referral-active-71'));
select set_config('request.jwt.claim.sub','a7100000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a7100000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into p20_observed values('award',public.award_reward('b7100000-0000-4000-8000-000000000002','d7100000-0000-4000-8000-000000000001','d7100000-0000-4000-8000-000000000003','CLIENT_PROJECT','d7100000-0000-4000-8000-000000000002',repeat('a',64),jsonb_build_object('source_event_id',(select v->>'source_event_id'from p20_observed where k='source')),(select v->>'approval_id'from p20_observed where k='approval'),'reward-award-happy-71'));
insert into p20_observed values('award-replay',public.award_reward('b7100000-0000-4000-8000-000000000002','d7100000-0000-4000-8000-000000000001','d7100000-0000-4000-8000-000000000003','CLIENT_PROJECT','d7100000-0000-4000-8000-000000000002',repeat('a',64),jsonb_build_object('source_event_id',(select v->>'source_event_id'from p20_observed where k='source')),(select v->>'approval_id'from p20_observed where k='approval'),'reward-award-happy-71'));
reset role;
select is((select v->>'outcome'from p20_observed where k='source'),'REWARD_SOURCE_EVENT_RECORDED','durable project produces authoritative reward event');
select is((select v->>'outcome'from p20_observed where k='award'),'REWARD_GRANTED','approved reward happy path completes');
select is((select v->>'reward_grant_id'from p20_observed where k='award'),(select v->>'reward_grant_id'from p20_observed where k='award-replay'),'reward replay is idempotent');
select is((select sum(quantity)::bigint from public.credit_ledger_entries where organization_id='b7100000-0000-4000-8000-000000000002'),25::bigint,'happy reward appends exact credit quantity');
select is((select conversion_stage from public.referral_conversions where id='d7100000-0000-4000-8000-000000000010'),'ACTIVE','two distinct central actors complete VERIFIED to ACTIVE');
select isnt((select actor_user_id from public.referral_conversion_events where referral_conversion_id='d7100000-0000-4000-8000-000000000010'and to_stage='VERIFIED'),(select actor_user_id from public.referral_conversion_events where referral_conversion_id='d7100000-0000-4000-8000-000000000010'and to_stage='ACTIVE'),'VERIFIED and ACTIVE use different decision actors');
select extensions.throws_ok(format($sql$set local role authenticated;select public.award_reward('b7100000-0000-4000-8000-000000000002','d7100000-0000-4000-8000-000000000012','d7100000-0000-4000-8000-000000000003','CLIENT_PROJECT','d7100000-0000-4000-8000-000000000002',repeat('f',64),jsonb_build_object('source_event_id',%L),%L,'reward-wallet-deny-71')$sql$,(select v->>'source_event_id'from p20_observed where k='source'),(select v->>'approval_id'from p20_observed where k='approval')),'23514'::char(5),'REWARD_WALLET_AUDIENCE_MISMATCH','client-audience reward cannot credit a provider wallet');

select extensions.throws_ok($$insert into public.referral_conversions(referral_link_id,source_organization_id,target_organization_id,audience_type,conversion_stage,origin_snapshot,registered_by)values('d7100000-0000-4000-8000-000000000009','b7100000-0000-4000-8000-000000000001','b7100000-0000-4000-8000-000000000003','PROVIDER','REGISTERED','{}','a7100000-0000-4000-8000-000000000003')$$,'23514'::char(5),'REFERRAL_AUDIENCE_MISMATCH','conversion cannot contradict referral link audience');
set local role authenticated;select set_config('request.jwt.claim.sub','a7100000-0000-4000-8000-000000000003',true);select set_config('request.jwt.claims','{"sub":"a7100000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);reset role;
select extensions.throws_ok($$set local role authenticated;select public.record_referral_touchpoint('UNKNOWN71','LINK_OPENED',repeat('b',64),'oracle-unknown-71')$$,'42501'::char(5),'REFERRAL_REQUEST_DENIED','unknown referral code is anti-oracle denied');
select extensions.throws_ok($$set local role authenticated;select public.record_referral_touchpoint('AUDIENCE71','INVALID',repeat('b',64),'oracle-invalid-71')$$,'42501'::char(5),'REFERRAL_REQUEST_DENIED','invalid known-code request has the same anti-oracle denial');
set local role authenticated;
insert into p20_observed values('baseline-valid',public.capture_verified_baseline('b7100000-0000-4000-8000-000000000002','ORGANIZATION','b7100000-0000-4000-8000-000000000002','VALID_EVIDENCE',1000,'MAD','2026-01-01','2026-01-31','AUDITED_IMPORT','valid:evidence',jsonb_build_array(jsonb_build_object('registry','CLIENT_COMPLIANCE_EVIDENCE','id','d7100000-0000-4000-8000-000000000007')),repeat('c',64),'EVIDENCE-V1','baseline-valid-71'));
reset role;
select is((select v->>'outcome'from p20_observed where k='baseline-valid'),'MEASUREMENT_BASELINE_DRAFT_SUBMITTED','verified tenant registry evidence allows baseline draft');
select extensions.throws_ok($$set local role authenticated;select public.capture_verified_baseline('b7100000-0000-4000-8000-000000000002','ORGANIZATION','b7100000-0000-4000-8000-000000000002','FOREIGN_EVIDENCE',1000,'MAD','2026-01-01','2026-01-31','AUDITED_IMPORT','foreign:evidence','[{"registry":"CLIENT_COMPLIANCE_EVIDENCE","id":"d7100000-0000-4000-8000-000000000008"}]',repeat('d',64),'EVIDENCE-V1','baseline-foreign-71')$$,'23514'::char(5),'VERIFIED_TENANT_EVIDENCE_REQUIRED','foreign-tenant evidence cannot support baseline');
select extensions.throws_ok($$set local role authenticated;select public.capture_verified_baseline('b7100000-0000-4000-8000-000000000002','ORGANIZATION','b7100000-0000-4000-8000-000000000002','STRING_EVIDENCE',1000,'MAD','2026-01-01','2026-01-31','AUDITED_IMPORT','string:evidence','["unresolved:string"]',repeat('e',64),'EVIDENCE-V1','baseline-string-71')$$,'23514'::char(5),'VERIFIED_TENANT_EVIDENCE_REQUIRED','unresolved string evidence cannot support baseline');

select * from finish();rollback;
